SELECT ca.ca_state, td.t_hour, SUM(ss.ss_net_paid) AS total_net_paid, (SELECT COUNT(*) FROM store_sales ss2 WHERE ss2.ss_sold_date_sk = 2452260) AS total_sales_on_date FROM store_sales ss JOIN time_dim td ON ss.ss_sold_time_sk = td.t_time_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number WHERE ss.ss_sold_date_sk = 2452599 AND sr.sr_return_quantity > 60 GROUP BY ca.ca_state, td.t_hour HAVING SUM(ss.ss_net_paid) > 366.12
